describe("冻结完整诊断码与误贴凭据拒绝回归", () => {
  const cases = [
    ["connection_tls_untrusted", "证书或服务器身份不可信", 422],
    ["connection_auth_failed", "源账号认证失败", 422],
    ["connection_readonly_unverified", "无法证明源账号仅有只读权限", 422],
    ["connection_source_unavailable", "源服务暂不可用", 503],
  ] as const;
  it.each(cases)("%s HTTP错误显示独立安全诊断", (code, expected, status) => {
    const html = renderToStaticMarkup(createElement(RequestError, { error: new PlatformApiError(status, code) }));
    expect(html).toContain(expected);
    expect(html).not.toContain("配置或凭据未通过验证");
  });
  it.each(cases)("%s 失败Probe不伪造通过或泄露原异常", (code, expected) => {
    const probe = { status: "TEST_FAILED", stages: [{ name: "AUTH", status: "FAIL", durationMs: 1, diagnosticCode: code }], stale: false } as ConnectionProbeView;
    const html = renderToStaticMarkup(createElement(ProbeReport, { probe }));
    expect(html).toContain(expected); expect(html).toContain("测试失败"); expect(html).not.toContain("测试通过");
    expect(html.match(/未验证/g)).toHaveLength(4);
  });
  it("未知诊断不回显任意异常正文", () => {
    const probe = { status: "TEST_FAILED", stages: [{ name: "AUTH", status: "FAIL", durationMs: 1, diagnosticCode: "Password=must-not-display" }], stale: false } as ConnectionProbeView;
    const html = renderToStaticMarkup(createElement(ProbeReport, { probe }));
    expect(html).not.toContain("must-not-display"); expect(html).toContain("此阶段未通过");
  });
  it.each([
    ["POSTGRESQL", "host", "Host=pg-source;Username=reader;Password=private-password"],
    ["ORACLE", "host", "Data Source=oracle;User Id=reader;Pwd=private-password"],
    ["DORIS", "feHost", "mysql://reader:private-password@doris"],
    ["POSTGRESQL", "database", "Password=private-password"],
  ])("%s %s误贴连接串不会写入或恢复", (type, key, value) => {
    const original = validForms[type as ConnectionType];
    const form = { ...original, values: { ...original.values, [key]: value } };
    expect(encodeDraft(form)).not.toContain("private-password");
    expect(decodeDraft(JSON.stringify(form))?.values[key]).toBe("");
  });
});


describe("URL草稿缓存不持久化查询参数或片段", () => {
  const cases = ["token", "access_token", "password"].flatMap(key => [
    `?${key}=synthetic-secret`, `?locale=zh&${key}=synthetic-secret`, `#${key}=synthetic-secret`,
  ]);
  it.each(cases)("TDengine %s仅留内存，读写缓存都拒绝", suffix => {
    const form = { ...validForms.TDENGINE, values: { ...validForms.TDENGINE.values, wsUrl: `wss://td.example/ws${suffix}` } };
    expect(validateForm(form)).toEqual({});
    expect(encodeDraft(form)).not.toContain("synthetic-secret");
    expect(decodeDraft(JSON.stringify(form))?.values.wsUrl).toBe("");
    expect(form.values.wsUrl).toContain(suffix);
  });
  it.each(["baseOrigin", "approvedPath"])("Web API %s所有query/fragment均不缓存", key => {
    for (const suffix of ["?token=synthetic-secret", "#password=synthetic-secret", "?locale=zh", "#section", "?", "#"]) {
      const form = { ...validForms.WEB_API, values: { ...validForms.WEB_API.values, [key]: `${key === "baseOrigin" ? "https://api.example" : "/fixture"}${suffix}` } };
      expect(JSON.parse(encodeDraft(form)).values[key]).toBe("");
      expect(decodeDraft(JSON.stringify(form))?.values[key]).toBe("");
      expect(form.values[key]).toContain(suffix);
    }
  });
  it("不含query/fragment/userinfo的URL可保留", () => {
    expect(decodeDraft(encodeDraft(validForms.TDENGINE))).toEqual(validForms.TDENGINE);
    expect(decodeDraft(encodeDraft(validForms.WEB_API))).toEqual(validForms.WEB_API);
  });
});

/** 已授权任务与源目录分别返回，测试仅验证真实组件在这些输入下的状态清理。 */
describe("目录拒绝后的任务诊断与权限重验（组件回归）", () => {
  const connection = { id: "connection", state: "ACTIVE", probeFresh: true } as ConnectionView;
  const job = { jobId: "job", connectionId: "connection", status: "PARTIAL", createdAtUtc: "2026-11-01", traceId: "safe-trace" } as CatalogDiscoveryJobView;
  const snapshot = { snapshotId: "snapshot", status: "SUCCEEDED", capturedAtUtc: "2026-11-01", configRevision: 1, schemaFingerprint: "safe-hash", objects: [{ schema: "production", name: "old-private-table", kind: "TABLE", fields: [] }] } as unknown as CatalogSnapshotView;
  async function settle() { for (let index = 0; index < 30; index++) await Promise.resolve(); }
  function elements(node: ReactNode): Array<React.ReactElement<Record<string, unknown>>> {
    if (Array.isArray(node)) return node.flatMap(elements);
    if (!isValidElement<Record<string, unknown>>(node)) return [];
    return [node, ...elements(node.props.children as ReactNode)];
  }
  function setup(jobId = "job") {
    catalogHarness.jobId = jobId; catalogHarness.replace.mockReset();
    for (const mock of Object.values(catalogHarness.api)) mock.mockReset();
    catalogHarness.api.get.mockResolvedValue({ data: connection });
    catalogHarness.api.job.mockResolvedValue({ data: job });
    catalogHarness.api.catalogs.mockRejectedValue(new PlatformApiError(403, "catalog_access_forbidden"));
    const host = new catalogHarness.Host(); const onDenied = vi.fn();
    const render = () => host.render(() => CatalogPanel({ connection, etag: '"1"', canManage: true, onDenied }));
    return { host, onDenied, render, html: () => renderToStaticMarkup(render()) };
  }
  it("源目录403后重新授权连接和任务，显示PARTIAL但不恢复目录", async () => {
    const view = setup(); view.render(); await settle();
    const html = view.html();
    expect(catalogHarness.api.get).toHaveBeenCalledWith("connection", expect.any(AbortSignal));
    expect(catalogHarness.api.job.mock.calls.length).toBeGreaterThan(1);
    expect(html).toContain("发现未完整完成"); expect(html).not.toContain("目录快照历史");
    expect(view.onDenied).not.toHaveBeenCalled(); view.host.unmount();
  });
  it("重验任务仍RUNNING时保留显式继续入口，不假称PARTIAL", async () => {
    const view = setup(); catalogHarness.api.job.mockResolvedValue({ data: { ...job, status: "RUNNING" } });
    view.render(); await settle(); const html = view.html();
    expect(html).toContain("继续读取任务状态"); expect(html).not.toContain("发现未完整完成");
    expect(view.onDenied).not.toHaveBeenCalled(); view.host.unmount();
  });
  it.each(["connection", "job"])("%s 重验403必须全清并向父页拒绝", async kind => {
    const view = setup();
    if (kind === "connection") catalogHarness.api.get.mockRejectedValue(new PlatformApiError(403, "connection_scope_forbidden"));
    else catalogHarness.api.job.mockResolvedValueOnce({ data: job }).mockRejectedValue(new PlatformApiError(403, "connection_scope_forbidden"));
    view.render(); await settle();
    expect(view.onDenied).toHaveBeenCalled(); expect(view.html()).not.toContain("发现未完整完成"); view.host.unmount();
  });
  it.each([[401, "authentication_required"], [403, "connection_scope_forbidden"], [403, "unknown_forbidden"]])("目录HTTP %s/%s不能降级为源ACL拒绝", async (status, code) => {
    const view = setup(); catalogHarness.api.catalogs.mockRejectedValue(new PlatformApiError(Number(status), String(code)));
    view.render(); await settle();
    expect(view.onDenied).toHaveBeenCalled(); expect(catalogHarness.api.get).not.toHaveBeenCalled();
    expect(view.html()).not.toContain("发现未完整完成"); view.host.unmount();
  });
  it.each([true, false])("无jobId时仍重验连接，授权结果=%s", async allowed => {
    const view = setup("");
    if (!allowed) catalogHarness.api.get.mockRejectedValue(new PlatformApiError(403, "connection_scope_forbidden"));
    view.render(); await settle();
    expect(catalogHarness.api.get).toHaveBeenCalledTimes(1); expect(catalogHarness.api.job).not.toHaveBeenCalled();
    expect(view.onDenied.mock.calls.length > 0).toBe(!allowed); view.host.unmount();
  });
  it("重验发现连接已禁用时不能保留任务或目录", async () => {
    const view = setup(); catalogHarness.api.get.mockResolvedValue({ data: { ...connection, state: "DISABLED" } });
    view.render(); await settle(); expect(view.onDenied).toHaveBeenCalled(); expect(view.html()).not.toContain("发现未完整完成"); view.host.unmount();
  });
  it("目录被拒绝后立即清空此前成功显示的快照和历史", async () => {
    const view = setup(""); catalogHarness.api.catalogs.mockResolvedValue({ data: { items: [snapshot], nextCursor: null } });
    catalogHarness.api.catalog.mockResolvedValueOnce({ data: snapshot }).mockRejectedValue(new PlatformApiError(403, "catalog_access_forbidden"));
    view.render(); await settle();
    const clickSnapshot = () => { const button = elements(view.render()).find(element => element.type === "button" && String(element.props.children).includes("个对象")); expect(button).toBeDefined(); (button!.props.onClick as () => void)(); };
    clickSnapshot(); await settle(); expect(view.html()).toContain("old-private-table");
    clickSnapshot(); await settle(); const html = view.html();
    expect(html).not.toContain("old-private-table"); expect(html).not.toContain("目录快照历史"); expect(view.onDenied).not.toHaveBeenCalled(); view.host.unmount();
  });
  it("卸载后迟到的连接重验响应不得触发任务读取或恢复投影", async () => {
    const view = setup(); let complete!: (value: unknown) => void;
    catalogHarness.api.get.mockReturnValue(new Promise(resolve => { complete = resolve; }));
    view.render(); await settle(); const jobCalls = catalogHarness.api.job.mock.calls.length;
    view.host.unmount(); const slots = [...view.host.slots]; complete({ data: connection }); await settle();
    expect(catalogHarness.api.job).toHaveBeenCalledTimes(jobCalls); expect(view.host.slots).toEqual(slots); expect(view.onDenied).not.toHaveBeenCalled();
  });
  it.each([200, 403])("初始目录读取及源拒绝重验完成前禁止发现，结果%s后授权恢复", async status => {
    const view = setup(""); let resolveCatalog!: (value: unknown) => void; let rejectCatalog!: (cause: Error) => void; let resolveRevalidation!: (value: unknown) => void;
    catalogHarness.api.catalogs.mockReturnValue(new Promise((resolve, reject) => { resolveCatalog = resolve; rejectCatalog = reject; }));
    catalogHarness.api.get.mockReturnValue(new Promise(resolve => { resolveRevalidation = resolve; }));
    catalogHarness.api.discover.mockResolvedValue({ data: job });
    const discover = () => elements(view.render()).find(element => element.type === "button" && element.props.children === "发现目录")!;
    view.render(); await settle();
    expect(discover().props.disabled).toBe(true); (discover().props.onClick as () => void)(); expect(catalogHarness.api.discover).not.toHaveBeenCalled();
    if (status === 403) { rejectCatalog(new PlatformApiError(403, "catalog_access_forbidden")); await settle(); expect(discover().props.disabled).toBe(true); (discover().props.onClick as () => void)(); expect(catalogHarness.api.discover).not.toHaveBeenCalled(); resolveRevalidation({ data: connection }); }
    else resolveCatalog({ data: { items: [] } });
    await settle(); expect(discover().props.disabled).toBe(false); (discover().props.onClick as () => void)(); await settle();
    expect(catalogHarness.api.discover).toHaveBeenCalledTimes(1); expect(catalogHarness.replace).toHaveBeenCalledWith("/data/connections?job=job"); view.host.unmount();
  });
  it.each(["history", "job"])("%s先结束不能释放另一读取的互锁", async first => {
    const view = setup(); let finishHistory!: (value: unknown) => void; let finishJob!: (value: unknown) => void;
    catalogHarness.api.catalogs.mockReturnValue(new Promise(resolve => { finishHistory = resolve; }));
    catalogHarness.api.job.mockReturnValue(new Promise(resolve => { finishJob = resolve; }));
    catalogHarness.api.cancel.mockResolvedValue({ data: job });
    view.render(); await settle();
    if (first === "history") finishHistory({ data: { items: [] } }); else finishJob({ data: { ...job, status: "RUNNING" } });
    await settle();
    const controls = elements(view.render()).filter(element => element.type === "button" && ["发现目录", "取消发现"].includes(String(element.props.children)));
    for (const control of controls) { expect(control.props.disabled).toBe(true); (control.props.onClick as () => void)(); }
    expect(catalogHarness.api.discover).not.toHaveBeenCalled(); expect(catalogHarness.api.cancel).not.toHaveBeenCalled();
    if (first === "history") finishJob({ data: { ...job, status: "RUNNING" } }); else finishHistory({ data: { items: [] } });
    await settle(); const cancel = elements(view.render()).find(element => element.type === "button" && element.props.children === "取消发现")!;
    expect(cancel.props.disabled).toBe(false); view.host.unmount();
  });
  it.each([[401, "authentication_required"], [403, "connection_scope_forbidden"]])("取消待响应时轮询%s撤权，旧响应不得恢复任务", async (status, code) => {
    vi.useFakeTimers(); const view = setup(); let finishCancel!: (value: unknown) => void;
    try {
      catalogHarness.api.catalogs.mockResolvedValue({ data: { items: [] } });
      catalogHarness.api.job.mockResolvedValueOnce({ data: { ...job, status: "RUNNING" } }).mockRejectedValue(new PlatformApiError(Number(status), String(code)));
      catalogHarness.api.cancel.mockReturnValue(new Promise(resolve => { finishCancel = resolve; }));
      view.render(); await settle(); const cancel = elements(view.render()).find(element => element.type === "button" && element.props.children === "取消发现")!;
      expect(cancel.props.disabled).toBe(false); (cancel.props.onClick as () => void)(); await settle();
      await vi.advanceTimersByTimeAsync(1500); finishCancel({ data: { ...job, status: "CANCELLED" } }); await settle();
      expect(view.onDenied).toHaveBeenCalled(); expect(view.html()).not.toContain("目录发现："); expect(view.html()).not.toContain("恢复上次目录操作结果"); expect(catalogHarness.replace).not.toHaveBeenCalled();
    } finally { view.host.unmount(); vi.useRealTimers(); }
  });
  it("旧取消503晚于轮询源目录403重验时不得覆盖权限提示", async () => {
    vi.useFakeTimers(); const view = setup(); let rejectCancel!: (cause: Error) => void;
    try {
      catalogHarness.api.catalogs.mockResolvedValueOnce({ data: { items: [] } }).mockRejectedValue(new PlatformApiError(403, "catalog_access_forbidden"));
      catalogHarness.api.job.mockResolvedValueOnce({ data: { ...job, status: "RUNNING" } }).mockResolvedValue({ data: job });
      catalogHarness.api.cancel.mockReturnValue(new Promise((_, reject) => { rejectCancel = reject; }));
      view.render(); await settle(); const cancel = elements(view.render()).find(element => element.type === "button" && element.props.children === "取消发现")!;
      expect(cancel.props.disabled).toBe(false); (cancel.props.onClick as () => void)(); await settle();
      await vi.advanceTimersByTimeAsync(1500); rejectCancel(new PlatformApiError(503, "request_failed")); await settle();
      expect(view.html()).toContain("没有访问权限"); expect(view.html()).not.toContain("服务暂不可用"); expect(view.html()).toContain("发现未完整完成"); expect(view.onDenied).not.toHaveBeenCalled(); expect(catalogHarness.replace).not.toHaveBeenCalled();
    } finally { view.host.unmount(); vi.useRealTimers(); }
  });
  it.each(["success", "failure"])("正常发现后卸载，迟到%s不得导航或恢复旧状态", async outcome => {
    const view = setup(""); let resolveDiscover!: (value: unknown) => void; let rejectDiscover!: (cause: Error) => void;
    catalogHarness.api.catalogs.mockResolvedValue({ data: { items: [] } });
    catalogHarness.api.discover.mockReturnValue(new Promise((resolve, reject) => { resolveDiscover = resolve; rejectDiscover = reject; }));
    view.render(); await settle(); const discover = elements(view.render()).find(element => element.type === "button" && element.props.children === "发现目录")!;
    expect(discover.props.disabled).toBe(false); (discover.props.onClick as () => void)(); await settle(); view.host.unmount(); const slots = [...view.host.slots];
    if (outcome === "success") resolveDiscover({ data: job }); else rejectDiscover(new PlatformApiError(503, "request_failed"));
    await settle(); expect(catalogHarness.replace).not.toHaveBeenCalled(); expect(view.host.slots).toEqual(slots);
  });
  it("目录401后迟到的旧任务成功不得重新恢复诊断", async () => {
    const view = setup(); let complete!: (value: unknown) => void;
    catalogHarness.api.catalogs.mockRejectedValue(new PlatformApiError(401, "authentication_required"));
    catalogHarness.api.job.mockReturnValue(new Promise(resolve => { complete = resolve; }));
    view.render(); await settle(); complete({ data: job }); await settle();
    expect(view.onDenied).toHaveBeenCalled(); expect(view.html()).not.toContain("发现未完整完成"); view.host.unmount();
  });
});

/** 调度真实父子事件与 key 卸载，延迟的是客户端 Promise，不替代浏览器或真实网络验收。 */
describe("详情与目录操作的异步互锁（组件回归）", () => {
  async function settle() { for (let index = 0; index < 30; index++) await Promise.resolve(); }
  function elements(node: ReactNode): Array<React.ReactElement<Record<string, unknown>>> {
    if (Array.isArray(node)) return node.flatMap(elements);
    if (!isValidElement<Record<string, unknown>>(node)) return [];
    return [node, ...elements(node.props.children as ReactNode)];
  }
  function button(node: ReactNode, label: string) {
    const result = elements(node).find(element => element.type === "button" && element.props.children === label);
    expect(result).toBeDefined(); return result!;
  }
  function click(node: ReactNode, label: string) {
    const target = button(node, label);
    if (!target.props.disabled) (target.props.onClick as () => void)();
  }
  function setup(state = "DRAFT") {
    catalogHarness.jobId = ""; catalogHarness.replace.mockReset();
    for (const mock of Object.values(catalogHarness.api)) mock.mockReset();
    const connection = { id: "connection", displayName: "合成连接", config: configFromForm(validForms.POSTGRESQL), scope, state, probeFresh: true, lastProbeId: "probe", configRevision: 1 } as ConnectionView;
    const job = { jobId: "discovered-job", connectionId: connection.id, status: "QUEUED" } as CatalogDiscoveryJobView;
    catalogHarness.api.get.mockResolvedValue({ data: connection, etag: '"1"' });
    catalogHarness.api.probe.mockResolvedValue({ data: { probeId: "probe", stages: [], status: "TEST_OK" } });
    catalogHarness.api.catalogs.mockResolvedValue({ data: { items: [], nextCursor: null } });
    catalogHarness.api.transition.mockResolvedValue({ data: { ...connection, state: "ACTIVE" }, etag: '"1"' });
    catalogHarness.api.discover.mockResolvedValue({ data: job });
    const parent = new catalogHarness.Host(); let child = new catalogHarness.Host(); let key: string | null = null;
    function render() {
      const detail = parent.render(() => ConnectionDetail({ id: connection.id, canManage: true }));
      const panel = elements(detail).find(element => element.type === CatalogPanel);
      if (!panel) return { detail, catalog: null };
      if (key !== panel.key) { child.unmount(); child = new catalogHarness.Host(); key = panel.key; }
      const catalog = child.render(() => CatalogPanel(panel.props as Parameters<typeof CatalogPanel>[0]));
      return { detail, catalog };
    }
    return { connection, job, render, remountCatalog: () => { child.unmount(); child = new catalogHarness.Host(); key = null; }, unmount: () => { child.unmount(); parent.unmount(); } };
  }
  it("启用已返回但父级刷新未结束时不发送发现，完成后恢复发现并保存 job URL", async () => {
    const view = setup(); view.render(); await settle(); view.render(); await settle();
    let finishRefresh!: (value: unknown) => void;
    catalogHarness.api.get.mockReturnValue(new Promise(resolve => { finishRefresh = resolve; }));
    click(view.render().detail, "明确启用连接"); await settle();
    const pending = view.render();
    expect(renderToStaticMarkup(pending.detail)).toContain("正在启用连接");
    // 即使真实 DOM 会禁止单击，也直接调用事件验证入口不会绕过父级忙碌保护。
    (button(pending.catalog, "发现目录").props.onClick as () => void)(); await settle();
    expect(catalogHarness.api.discover).toHaveBeenCalledTimes(0);
    expect(button(pending.catalog, "发现目录").props.disabled).toBe(true);
    finishRefresh({ data: { ...view.connection, state: "ACTIVE" }, etag: '"1"' }); await settle();
    view.render(); await settle(); const ready = view.render(); expect(button(ready.catalog, "发现目录").props.disabled).toBe(false);
    click(ready.catalog, "发现目录"); await settle();
    expect(catalogHarness.api.discover).toHaveBeenCalledTimes(1);
    expect(catalogHarness.replace).toHaveBeenCalledWith("/data/connections?job=discovered-job"); view.unmount();
  });
  it("目录发现先开始时父级刷新不能卸载该任务，返回后恢复刷新且保留 job URL", async () => {
    const view = setup("ACTIVE"); view.render(); await settle(); view.render(); await settle();
    let finishDiscover!: (value: unknown) => void;
    catalogHarness.api.discover.mockReturnValue(new Promise(resolve => { finishDiscover = resolve; }));
    click(view.render().catalog, "发现目录"); await settle();
    const pending = view.render(); const calls = catalogHarness.api.get.mock.calls.length;
    click(pending.detail, "刷新详情"); await settle(); view.render();
    expect(catalogHarness.api.get).toHaveBeenCalledTimes(calls);
    expect(button(pending.detail, "刷新详情").props.disabled).toBe(true);
    finishDiscover({ data: view.job }); await settle();
    expect(catalogHarness.replace).toHaveBeenCalledWith("/data/connections?job=discovered-job");
    expect(button(view.render().detail, "刷新详情").props.disabled).toBe(false); view.unmount();
  });
  it("旧面板卸载后的迟到 finally 不得释放新面板正在执行的锁", async () => {
    const view = setup("ACTIVE"); view.render(); await settle(); view.render(); await settle();
    let finishOld!: (value: unknown) => void; let finishNew!: (value: unknown) => void;
    catalogHarness.api.discover.mockReturnValueOnce(new Promise(resolve => { finishOld = resolve; })).mockReturnValueOnce(new Promise(resolve => { finishNew = resolve; }));
    click(view.render().catalog, "发现目录"); await settle();
    view.remountCatalog(); view.render(); await settle(); const remounted = view.render(); click(remounted.catalog, "发现目录"); await settle();
    finishOld({ data: { ...view.job, jobId: "old-job" } }); await settle();
    expect(catalogHarness.replace).not.toHaveBeenCalled();
    const pending = view.render(); expect(button(pending.detail, "刷新详情").props.disabled).toBe(true);
    const calls = catalogHarness.api.get.mock.calls.length;
    (button(pending.detail, "刷新详情").props.onClick as () => void)(); await settle();
    expect(catalogHarness.api.get).toHaveBeenCalledTimes(calls);
    finishNew({ data: view.job }); await settle();
    expect(catalogHarness.replace).toHaveBeenCalledWith("/data/connections?job=discovered-job");
    expect(button(view.render().detail, "刷新详情").props.disabled).toBe(false); view.unmount();
  });
  it("目录请求失败释放父锁并保留可用的明确恢复入口", async () => {
    const view = setup("ACTIVE"); view.render(); await settle(); view.render(); await settle();
    catalogHarness.api.discover.mockRejectedValueOnce(new PlatformApiError(503, "request_failed"));
    click(view.render().catalog, "发现目录"); await settle();
    const failed = view.render(); expect(button(failed.detail, "刷新详情").props.disabled).toBe(false);
    expect(button(failed.catalog, "恢复上次目录操作结果").props.disabled).toBe(false);
